import {portalConfig} from './firebase-config.js';
let auth,sdk,functions,callSdk,profile=null,recaptcha,confirmation,ready=false;
const configured=portalConfig.enabled&&['apiKey','authDomain','projectId','appId','storageBucket'].every(k=>portalConfig.firebase[k])&&portalConfig.appCheckSiteKey;
export const backend={enabled:!!configured,get profile(){return profile},get user(){return auth?.currentUser},get ready(){return ready}};
const errorText=e=>({'auth/invalid-credential':'The sign-in details are incorrect.','auth/email-already-in-use':'An account already uses this email. Sign in or reset your password.','auth/weak-password':'Use a stronger password with at least 12 characters.','auth/popup-closed-by-user':'Google sign-in was cancelled.','auth/too-many-requests':'Too many attempts. Please try again later.','auth/invalid-verification-code':'The verification code is incorrect.','auth/code-expired':'This code has expired. Request another code.','auth/unauthorized-domain':'Sign-in is not yet enabled for this website.','auth/account-exists-with-different-credential':'Sign in with your existing method before linking another provider.'}[e?.code]||e?.message||'Unable to complete this request.');
export async function initFirebase(onChange){
 if(portalConfig.enabled&&!configured)throw new Error('Firebase configuration is incomplete. Contact the portal administrator.');if(portalConfig.enabled&&!/^https:\/\//.test(portalConfig.privacyUrl))throw new Error('An approved privacy notice URL is required before activation.');if(!backend.enabled){ready=true;return}
 const base='https://www.gstatic.com/firebasejs/13.0.0/';
 const [appModule,authModule,fnModule,checkModule]=await Promise.all(['firebase-app.js','firebase-auth.js','firebase-functions.js','firebase-app-check.js'].map(p=>import(base+p)));
 const app=appModule.initializeApp(portalConfig.firebase);sdk=authModule;callSdk=fnModule;
 checkModule.initializeAppCheck(app,{provider:new checkModule.ReCaptchaV3Provider(portalConfig.appCheckSiteKey),isTokenAutoRefreshEnabled:true});
 auth=sdk.getAuth(app);functions=fnModule.getFunctions(app,portalConfig.region);
 await sdk.setPersistence(auth,sdk.browserSessionPersistence);
 await new Promise(resolve=>{let first=true;sdk.onAuthStateChanged(auth,async user=>{
  profile=null;try{if(user){const intent=JSON.parse(sessionStorage.getItem('rcl-signup-intent')||'{}');profile=await call('portalBootstrap',intent);sessionStorage.removeItem('rcl-signup-intent')}}catch(e){profile={status:'error',error:errorText(e)}}
  ready=true;if(first){first=false;resolve()}else onChange?.();
 })});
}
export async function call(name,data={}){if(!backend.enabled||!functions)throw new Error('Firebase has not been configured.');return (await callSdk.httpsCallable(functions,name,{timeout:60000})(data)).data}
export async function logout(){recaptcha?.clear();recaptcha=null;confirmation=null;profile=null;await sdk.signOut(auth)}
export async function startGuest(){if(!backend.enabled)return;if(auth.currentUser){if(profile?.role!=='guest'&&profile?.role!=='student')throw new Error('Sign out of the agency account before starting a direct application.');return}await sdk.signInAnonymously(auth);profile=await call('portalBootstrap')}
export async function syncProfile(){await auth.currentUser?.reload();await auth.currentUser?.getIdToken(true);profile=await call('portalBootstrap');return profile}
export async function loadRecords(){return call('portalRecords')}
export async function saveApplication(a){return call('portalSaveApplication',{id:a.id,application:a,submit:a.status==='New Application'})}
export async function uploadDocument(a,type,file,previousId){const base64=await new Promise((res,rej)=>{const r=new FileReader();r.onerror=rej;r.onload=()=>res(r.result.split(',')[1]);r.readAsDataURL(file)});return call('portalUpload',{application:a.id,type,name:file.name,mime:file.type,base64,previousId})}
export async function downloadDocument(id){const d=await call('portalFile',{id});return {name:d.name,blob:new Blob([Uint8Array.from(atob(d.base64),c=>c.charCodeAt(0))],{type:d.mime})}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function authPage(root,brand,onSuccess){
 recaptcha?.clear();recaptcha=null;confirmation=null;
 const signup=location.hash==='#signup',reset=location.hash==='#reset',disabled=!backend.enabled;
 const user=auth?.currentUser;
 const notice=disabled?'Account services are being configured. Registration and sign-in are unavailable until the Firebase project is connected.':profile?.error||'';
 const waiting=user&&!user.isAnonymous;
 root.innerHTML='<header class="public-top">'+brand()+'<a class="text-btn" href="#apply">Direct application →</a></header><main class="public-main"><section class="card login auth-card"><div class="eyebrow">RCL Mumbai · '+(signup?'Account registration':'Account access')+'</div><h1>'+(waiting?'Your account':reset?'Reset your password':signup?'Create your account':'Welcome back')+'</h1>'+(notice?'<div class="note">'+esc(notice)+'</div>':'')+'<div id="auth-message" role="status" aria-live="polite"></div>'+
 (waiting?'<p>'+esc(user.email||user.phoneNumber)+'</p>'+(!profile?.verified?'<div class="note">Verify your email address using the link sent to your inbox.</div><button class="btn wide" id="verify-status">I have verified my email</button><button class="text-btn" id="resend-verification">Resend verification email</button>':profile?.status==='pending'?'<div class="note">Your agency registration is awaiting approval by Admissions. You will have access after your agency and recruiter have been assigned.</div><button class="btn wide" id="verify-status">Check approval status</button>':profile?.status==='active'?'<button class="btn wide" id="open-workspace">Open workspace</button>':'<p>Your account is not currently active. Contact Admissions.</p>')+'<button class="btn secondary wide" id="auth-signout" style="margin-top:16px">Sign out</button>':
 '<form id="auth-email">'+(signup?'<label class="field"><span>Full name</span><input name="name" required autocomplete="name" maxlength="120" '+(disabled?'disabled':'')+'></label><label class="field"><span>Agency / organisation</span><input name="organisation" required maxlength="180" '+(disabled?'disabled':'')+'></label>':'')+'<label class="field"><span>Email address</span><input name="email" type="email" required autocomplete="email" '+(disabled?'disabled':'')+'></label>'+(!reset?'<label class="field"><span>Password</span><input name="password" type="password" required minlength="'+(signup?'12':'1')+'" autocomplete="'+(signup?'new-password':'current-password')+'" '+(disabled?'disabled':'')+'></label>':'')+(signup&&portalConfig.studentAccounts?'<label class="field"><span>Account type</span><select name="accountType"><option value="agent">Agency partner (approval required)</option><option value="student">Student</option></select></label>':'')+'<button class="btn wide" type="submit" '+(disabled?'disabled':'')+'>'+(reset?'Send reset link':signup?'Register with email':'Sign in')+'</button></form>'+(!reset?'<div class="auth-divider">or</div><button class="btn secondary wide" id="google-login" '+(disabled?'disabled':'')+'>Continue with Google</button><details class="auth-phone"><summary>Continue with phone number</summary><form id="auth-phone"><label class="field"><span>Phone number with country code</span><input name="phone" type="tel" placeholder="+91 or +977…" required pattern="\\+[1-9][0-9]{7,14}" autocomplete="tel" '+(disabled?'disabled':'')+'></label><label class="check"><input name="consent" type="checkbox" required '+(disabled?'disabled':'')+'>I agree to receive a verification SMS. My phone number will be processed by Google for authentication and abuse prevention.</label><div id="phone-recaptcha"></div><button type="submit" class="btn secondary wide" '+(disabled?'disabled':'')+'>Send verification code</button></form><form id="auth-otp" hidden><label class="field"><span>6-digit verification code</span><input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><button class="btn wide">Verify code</button></form></details>':'')+'<p class="auth-links">'+(signup?'<a href="#login">Already registered? Sign in</a>':reset?'<a href="#login">Back to sign in</a>':'<a href="#signup">Register your agency</a><a href="#reset">Forgot password?</a>')+'</p>')+
 '<p class="subtitle">'+(portalConfig.studentAccounts?'Students and approved agency partners can access their own applications.':'Agency accounts require approval. Direct students can apply without registering.')+'</p>'+(disabled?'<p><a href="#">Return to portal preview</a></p>':'')+'</section></main>';
 const message=(s,error=false)=>{const el=document.querySelector('#auth-message');el.className=error?'error':'note';el.textContent=s};
 const run=async(action)=>{try{await action()}catch(e){message(errorText(e),true);if(recaptcha){recaptcha.clear();recaptcha=null;}const send=document.querySelector('#auth-phone button');if(send&&backend.enabled)send.disabled=false}};
 function intent(){const form=document.querySelector('#auth-email'),values=form?Object.fromEntries(new FormData(form)):{};sessionStorage.setItem('rcl-signup-intent',JSON.stringify({accountType:values.accountType||'agent',name:values.name||'',organisation:values.organisation||''}));}
 const email=document.querySelector('#auth-email');
 email?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const values=Object.fromEntries(new FormData(email));const button=email.querySelector('button');button.disabled=true;try{
 if(reset){await sdk.sendPasswordResetEmail(auth,values.email);message('If an account exists for this address, a reset link will be sent.');return}
 if(signup){intent();const result=await sdk.createUserWithEmailAndPassword(auth,values.email,values.password);await sdk.updateProfile(result.user,{displayName:values.name});await sdk.sendEmailVerification(result.user);message('Account created. Check your inbox to verify your email.')}
 else await sdk.signInWithEmailAndPassword(auth,values.email,values.password);
 await syncProfile();onSuccess();
 }finally{button.disabled=false}})});
 document.querySelector('#google-login')?.addEventListener('click',()=>run(async()=>{intent();await sdk.signInWithPopup(auth,new sdk.GoogleAuthProvider());await syncProfile();onSuccess()}));
 document.querySelector('#auth-phone')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{intent();const values=Object.fromEntries(new FormData(e.target));if(!values.consent)throw new Error('Consent is required for SMS authentication.');if(!recaptcha)recaptcha=new sdk.RecaptchaVerifier(auth,'phone-recaptcha',{size:'normal'});confirmation=await sdk.signInWithPhoneNumber(auth,values.phone,recaptcha);document.querySelector('#auth-otp').hidden=false;e.target.querySelector('button').disabled=true;message('Verification code sent. Enter the 6-digit code.');})});
 document.querySelector('#auth-otp')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{await confirmation.confirm(new FormData(e.target).get('code'));await syncProfile();onSuccess()})});
 document.querySelector('#verify-status')?.addEventListener('click',()=>run(async()=>{await syncProfile();onSuccess()}));
 document.querySelector('#resend-verification')?.addEventListener('click',()=>run(async()=>{await sdk.sendEmailVerification(auth.currentUser);message('Verification email sent.')}));
 document.querySelector('#auth-signout')?.addEventListener('click',()=>run(async()=>{await logout();onSuccess()}));
 document.querySelector('#open-workspace')?.addEventListener('click',()=>{location.hash='';onSuccess()});
}
